/// Try to increase the size of the parser stack.  Throws if the allocation
/// fails.
fn yyGrowStack(yy_p: *PikParser) !void {
    const yy_new_size = yy_p.stk0.len * 2 + 100;
    const yy_idx = (@intFromPtr(yy_p.tos) - @intFromPtr(yy_p.stack));
    const yyp_new = try yy_p.allocator.realloc(yy_p.stk0, yy_new_size);
    yy_p.stack = yyp_new.ptr;
    yy_p.stk0 = yyp_new;
    yy_p.tos = yyp_new.ptr + yy_idx;
    yy_p.stack_end = yyp_new.ptr + (yy_new_size - 1);
}


/// The following function deletes the "minor type" or semantic value
/// associated with a symbol.  The symbol can be either a terminal
/// or nonterminal. "yymajor" is the symbol code, and "yypminor" is
/// a pointer to the value to be deleted.  The code used to do the
/// deletions is derived from the %destructor and/or %token_destructor
/// directives of the input grammar.
///
fn yy_destructor(
  yypParser: *PikParser,    // The parser */
  yymajor: YYCODETYPE,     // Type code for object to destroy */
  yypminor: *YYMINORTYPE,   // The object to be destroyed */
) void {
    
    var p = yypParser.p; _ = .{&p};
    defer {
        
        yypParser.p = p;
    }
    _ = .{ yypminor }; // Unused variable ward
    const allocator = yypParser.allocator; _ = .{allocator};
    switch( yymajor ){
        // Here is inserted the actions which take place when a
        // terminal or non-terminal is destroyed.  This can happen
        // when the symbol is popped from the stack during a
        // reduce or during error processing or when a parser is
        // being destroyed before it is finished parsing.
        //
        // Note: during a reduce, the only symbols destroyed are those
        // which appear on the RHS of the rule, but which are *not* used
        // inside the C code.
        //
//******** Begin destructor definitions ***************************************/
        106, // statement_list 
        => {
// #line 659 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zy
pik_elist_free(p,(yypminor.@"?*PList"));
// #line 1872 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zig
        },
        107, // statement 
        => {
// #line 661 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zy
pik_elem_free(p,(yypminor.@"?*PObj"));
// #line 1878 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zig
        },
        108, // unnamed_statement 
        => {
// #line 663 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zy
pik_elem_free(p,(yypminor.@"?*PObj"));
// #line 1884 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zig
        },
        109, // basetype 
        => {
// #line 665 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zy
pik_elem_free(p,(yypminor.@"?*PObj"));
// #line 1890 /Users/atman/Dropbox/deck/z/pikchresque/src/pikchr.zig
        },
